__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"hipoxia",{enumerable:!0,get:function(){return o}});const o={numero:3,titulo:'Respira\xe7\xe3o e hip\xf3xia',resumo:'A falta de oxig\xeanio \xe9 silenciosa: o c\xe9rebro sente antes de voc\xea perceber.',tempoLeituraMin:25,objetivos:['Explicar como o oxig\xeanio chega \xe0s c\xe9lulas','Diferenciar os quatro tipos de hip\xf3xia','Conhecer o tempo de consci\xeancia \xfatil em cada altitude','Reconhecer os sinais de hip\xf3xia e de hiperventila\xe7\xe3o'],topicos:[{id:'3.1',midias:['simulador-o2'],titulo:'Como o oxig\xeanio chega \xe0s c\xe9lulas',pergunta:'O que acontece com o oxig\xeanio do ar at\xe9 chegar ao c\xe9rebro?',conteudo:{essencial:'Em altitude, o ar tem a mesma propor\xe7\xe3o de oxig\xeanio, cerca de 21%, mas a press\xe3o \xe9 menor. Com menos press\xe3o, menos oxig\xeanio entra no sangue.',explicacao:'O oxig\xeanio passa do ar para os alv\xe9olos (pequenos sacos no fim das vias respirat\xf3rias), depois para o sangue, onde a hemoglobina (prote\xedna que carrega oxig\xeanio) o leva at\xe9 as c\xe9lulas. O que empurra o oxig\xeanio nessa passagem \xe9 a press\xe3o parcial (a parte da press\xe3o total que cabe ao oxig\xeanio). Quanto mais alto, menor a press\xe3o do ar e menor esse "empurr\xe3o".',clinico:'A press\xe3o parcial de O\u2082 inspirada \xe9 FiO\u2082 \xd7 (press\xe3o barom\xe9trica \u2212 47 mmHg), descontando o vapor d\u2019\xe1gua a 37 \xb0C. Ao n\xedvel do mar a PAO\u2082 \xe9 de cerca de 100 mmHg. A 8.000 ft (cerca de 2.400 m) cai para cerca de 65\u201370 mmHg, ainda na parte plana da curva de dissocia\xe7\xe3o, com satura\xe7\xe3o perto de 90\u201393%. Acima de 10.000 ft a curva entra na por\xe7\xe3o \xedngreme e a satura\xe7\xe3o cai rapidamente.',pontosChave:['A porcentagem de oxig\xeanio n\xe3o muda com a altitude; a press\xe3o, sim.','O que importa \xe9 a press\xe3o parcial de oxig\xeanio.','A partir de 10.000 ft a satura\xe7\xe3o cai depressa.']}},{id:'3.2',midias:['classificar-hipoxia'],titulo:'Os quatro tipos de hip\xf3xia',pergunta:'Falta de oxig\xeanio \xe9 sempre por causa da altitude?',conteudo:{essencial:'N\xe3o. O oxig\xeanio pode faltar porque o ar est\xe1 rarefeito, porque o sangue n\xe3o consegue carreg\xe1-lo, porque a circula\xe7\xe3o est\xe1 lenta ou porque as c\xe9lulas n\xe3o conseguem us\xe1-lo.',explicacao:'A hip\xf3xia hip\xf3xica vem do ar com pouca press\xe3o de oxig\xeanio, t\xedpica da altitude. A hip\xeamica (ou an\xeamica) acontece quando o sangue carrega pouco oxig\xeanio, como na anemia ou na intoxica\xe7\xe3o por mon\xf3xido de carbono. A estagnante (ou circulat\xf3ria) ocorre quando o sangue circula devagar, por exemplo sob for\xe7as G ou no frio intenso. A histot\xf3xica acontece quando as c\xe9lulas n\xe3o conseguem usar o oxig\xeanio, como na intoxica\xe7\xe3o por cianeto ou pelo \xe1lcool.',clinico:'Na pr\xe1tica, os tipos se somam: um piloto fumante (carboxi-hemoglobina elevada) e an\xeamico tem toler\xe2ncia menor \xe0 altitude. O mon\xf3xido de carbono tem afinidade pela hemoglobina cerca de 200 a 250 vezes maior que a do oxig\xeanio e desvia a curva de dissocia\xe7\xe3o para a esquerda. Em vazamentos de escapamento em aeronaves a pist\xe3o, a hip\xf3xia hip\xeamica pode ocorrer em baixa altitude.',pontosChave:['Hip\xf3xica, hip\xeamica, estagnante e histot\xf3xica.','Os tipos podem se somar no mesmo tripulante.','Mon\xf3xido de carbono causa hip\xf3xia mesmo em baixa altitude.']}},{id:'3.3',midias:['grafico-tuc'],titulo:'Tempo de consci\xeancia \xfatil',pergunta:'Quanto tempo uma pessoa continua l\xfacida sem oxig\xeanio a 35.000 p\xe9s?',conteudo:{essencial:'Tempo de consci\xeancia \xfatil \xe9 o intervalo em que voc\xea ainda consegue agir corretamente depois de perder o oxig\xeanio. A 35.000 p\xe9s, ele dura de 30 segundos a 1 minuto.',explicacao:'N\xe3o \xe9 o tempo at\xe9 desmaiar, e sim o tempo em que ainda d\xe1 para colocar a m\xe1scara, avisar a tripula\xe7\xe3o e iniciar a descida. Quanto mais alto, menor esse tempo: cerca de 20 a 30 minutos a 18.000 p\xe9s, de 3 a 5 minutos a 25.000 p\xe9s, de 1 a 2 minutos a 30.000 p\xe9s e de 15 a 20 segundos a 40.000 p\xe9s.',clinico:'Os valores s\xe3o m\xe9dias de tripulantes em repouso. Exerc\xedcio, fadiga, fumo, doen\xe7a e descompress\xe3o r\xe1pida encurtam o tempo; a descompress\xe3o r\xe1pida pode reduzi-lo a cerca da metade. Por isso os procedimentos determinam colocar o oxig\xeanio imediatamente, antes de qualquer diagn\xf3stico da pane.',pontosChave:['35.000 ft: de 30 segundos a 1 minuto.','Descompress\xe3o r\xe1pida encurta o tempo.','Primeiro a m\xe1scara, depois o resto.'],alerta:'Em uma despressuriza\xe7\xe3o, coloque sua m\xe1scara antes de ajudar qualquer outra pessoa.'}},{id:'3.4',midias:['simulador-visao'],titulo:'Sinais, sintomas e treinamento',pergunta:'Como perceber que est\xe1 faltando oxig\xeanio?',conteudo:{essencial:'A hip\xf3xia costuma come\xe7ar sem dor: euforia, formigamento, vis\xe3o turva e dificuldade de pensar. O perigo \xe9 que ela tira justamente a capacidade de perceber o problema.',explicacao:'Os sintomas que a pr\xf3pria pessoa sente incluem calor, tontura, formigamento, vis\xe3o emba\xe7ada e falsa sensa\xe7\xe3o de bem-estar. Os sinais que outros podem ver s\xe3o l\xe1bios e unhas arroxeados (cianose), respira\xe7\xe3o acelerada, confus\xe3o e falta de coordena\xe7\xe3o. Cada pessoa tem uma combina\xe7\xe3o pr\xf3pria e repet\xedvel de sintomas, e o treinamento em c\xe2mara ensina a reconhec\xea-la.',clinico:'A vis\xe3o noturna \xe9 afetada j\xe1 a partir de cerca de 5.000 ft. Julgamento, mem\xf3ria recente e coordena\xe7\xe3o fina se degradam antes dos sinais objetivos. O treinamento em c\xe2mara hipob\xe1rica ou com dispositivos de respira\xe7\xe3o com mistura reduzida de oxig\xeanio permite identificar a "assinatura" individual. Conduta: oxig\xeanio a 100%, verificar o sistema e descer para altitude segura.',pontosChave:['Euforia e julgamento alterado v\xeam antes dos sinais vis\xedveis.','Cada pessoa tem sua pr\xf3pria assinatura de sintomas.','Oxig\xeanio a 100% e descida.']}},{id:'3.5',titulo:'Hiperventila\xe7\xe3o e hipocapnia',pergunta:'Respirar demais tamb\xe9m pode fazer mal?',conteudo:{essencial:'Sim. Respirar r\xe1pido demais, por ansiedade ou estresse, elimina g\xe1s carb\xf4nico em excesso e causa tontura e formigamento, sintomas parecidos com os da hip\xf3xia.',explicacao:'O g\xe1s carb\xf4nico ajuda a regular o fluxo de sangue para o c\xe9rebro. Quando ele cai demais (hipocapnia), os vasos do c\xe9rebro se contraem e surgem tontura, formigamento nas m\xe3os e ao redor da boca e, em casos intensos, espasmos musculares.',clinico:'A hipocapnia leva \xe0 alcalose respirat\xf3ria, com vasoconstri\xe7\xe3o cerebral e redu\xe7\xe3o do c\xe1lcio ionizado, o que explica parestesias e tetania. Como os quadros se confundem, a regra em voo \xe9 tratar primeiro como hip\xf3xia: oxig\xeanio a 100% e checagem do sistema. S\xf3 depois, descartada a hip\xf3xia, controlar o ritmo respirat\xf3rio.',pontosChave:['Hiperventila\xe7\xe3o e hip\xf3xia t\xeam sintomas parecidos.','Na d\xfavida, trate como hip\xf3xia.','Depois, controle o ritmo da respira\xe7\xe3o.']}}],teste:[{pergunta:'Por que h\xe1 menos oxig\xeanio dispon\xedvel em altitude?',opcoes:['A porcentagem de oxig\xeanio no ar diminui','A press\xe3o parcial de oxig\xeanio diminui','O nitrog\xeanio ocupa o lugar do oxig\xeanio','A temperatura baixa destr\xf3i o oxig\xeanio'],correta:1,explicacao:'O ar continua com cerca de 21% de oxig\xeanio; o que cai \xe9 a press\xe3o, e com ela a press\xe3o parcial de oxig\xeanio.',topico:'3.1'},{pergunta:'Intoxica\xe7\xe3o por mon\xf3xido de carbono causa qual tipo de hip\xf3xia?',opcoes:['Hip\xf3xica','Hip\xeamica','Estagnante','Histot\xf3xica'],correta:1,explicacao:'O mon\xf3xido de carbono ocupa a hemoglobina, e o sangue passa a carregar menos oxig\xeanio: hip\xf3xia hip\xeamica.',topico:'3.2'},{pergunta:'Qual \xe9 o tempo de consci\xeancia \xfatil aproximado a 35.000 p\xe9s?',opcoes:['De 5 a 10 minutos','De 3 a 5 minutos','De 30 segundos a 1 minuto','Menos de 5 segundos'],correta:2,explicacao:'A 35.000 p\xe9s, o tempo de consci\xeancia \xfatil \xe9 de cerca de 30 segundos a 1 minuto.',topico:'3.3'},{pergunta:'O que acontece com o tempo de consci\xeancia \xfatil em uma descompress\xe3o r\xe1pida?',opcoes:['Aumenta','N\xe3o muda','Pode cair para cerca da metade','Passa a depender s\xf3 da temperatura'],correta:2,explicacao:'Na descompress\xe3o r\xe1pida, o tempo de consci\xeancia \xfatil pode ser reduzido a cerca da metade.',topico:'3.3'},{pergunta:'Qual \xe9 o principal perigo da hip\xf3xia para quem est\xe1 voando?',opcoes:['Causar dor intensa imediata','Tirar a capacidade de perceber o pr\xf3prio problema','Provocar sempre desmaio s\xfabito','Afetar apenas a vis\xe3o'],correta:1,explicacao:'A hip\xf3xia altera o julgamento antes dos sinais vis\xedveis, e a pessoa pode n\xe3o perceber que est\xe1 em perigo.',topico:'3.4'},{pergunta:'Em voo, um tripulante sente tontura e formigamento. Qual \xe9 a primeira conduta?',opcoes:['Respirar dentro de um saco de papel','Esperar os sintomas passarem','Oxig\xeanio a 100% e checar o sistema','Aumentar a altitude para economizar combust\xedvel'],correta:2,explicacao:'Como hip\xf3xia e hiperventila\xe7\xe3o se confundem, trata-se primeiro como hip\xf3xia: oxig\xeanio a 100%.',topico:'3.5'}]}},952,[]);
